/** @file
 * @brief Deterministic NXP LPUART divisor and 8-N-1 receive sampler. */
#ifndef APP_LPUART_SIM_H
#define APP_LPUART_SIM_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#define APP_LPUART_MIN_OSR 4U
#define APP_LPUART_MAX_OSR 32U
#define APP_LPUART_MAX_SBR 8191U
#define APP_LPUART_MAX_SOURCE_CLOCK_HZ 100000000U
#define APP_LPUART_MAX_REQUESTED_BAUD  25000000U

/** Selected LPUART timing and persistent asynchronous sampling phase. */
typedef struct {
    /** LPUART asynchronous module clock in hertz. */
    uint32_t sourceClockHz;
    /** Baud rate generated by the remote transmitter. */
    uint32_t requestedBaud;
    /** Effective oversampling ratio, equal to BAUD[OSR] + 1. */
    uint8_t osr;
    /** BAUD[SBR] modulo divisor. */
    uint16_t sbr;
    /** Rounded effective receiver baud rate for display. */
    uint32_t actualBaud;
    /** Signed difference from the requested rate in parts per million. */
    int32_t errorPpm;
    /** Sampling-clock phase at the next transmitted start bit. */
    uint64_t phase;
} AppLpuartSimulator_t;

/** Outcome produced by sampling one complete packet. */
typedef struct {
    /** Bytes whose sampled data bits differ from the transmitter. */
    size_t changedBytes;
    /** Bytes whose sampled stop bit was low. */
    size_t framingErrors;
    /** True only when every byte and stop bit survived the sampler. */
    bool valid;
} AppLpuartSimulationResult_t;

/** Select the closest KW47 divisor pair and reset asynchronous phase. */
bool AppLpuartSim_Configure(AppLpuartSimulator_t *simulator,
                            uint32_t sourceClockHz, uint32_t requestedBaud);

/** Sample a continuous 8-N-1 packet through the configured receiver.
 *
 * The output always contains @p length bytes. Invalid data is not discarded,
 * allowing downstream framing and CRC logic to experience the simulated wire.
 */
AppLpuartSimulationResult_t AppLpuartSim_Receive(
    AppLpuartSimulator_t *simulator, const uint8_t *input,
    uint8_t *output, size_t length);

#endif
